insert into public.branches (id, name, slug, address, area, city, phone, email, hours_note, opening_hours, directions_url, google_review_url, image_url, is_active, is_verified, source_note, display_order) values
  ('b0000000-0000-4000-8000-000000000001', 'MADNESS Bluewaters', 'bluewaters', 'Bluewaters Island, Dubai', 'Bluewaters', 'Dubai', '+971 4 422 4500', null, '12 PM to 1 AM. Walk-ins only, no reservations.', '[{"day":"mon","opens":"12:00","closes":"01:00"},{"day":"tue","opens":"12:00","closes":"01:00"},{"day":"wed","opens":"12:00","closes":"01:00"},{"day":"thu","opens":"12:00","closes":"01:00"},{"day":"fri","opens":"12:00","closes":"01:00"},{"day":"sat","opens":"12:00","closes":"01:00"},{"day":"sun","opens":"12:00","closes":"01:00"}]'::jsonb, 'https://goo.gl/maps/3So9kcQNgcGJfzi88', null, '/images/interior-neon-booths.webp', true, false, 'From the @madness.uae Instagram bio (checked 26 Oct 2026): phone, 12PM to 1AM, no reservation, map link. Full street address still needed.', 1),
  ('b0000000-0000-4000-8000-000000000002', 'MADNESS Jumeirah', 'jumeirah', '609 Jumeira St, Umm Suqeim 1, Dubai', 'Umm Suqeim', 'Dubai', '+971 4 340 0103', null, 'Opening hours to be confirmed.', '[]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=609%20Jumeira%20St%2C%20Umm%20Suqeim%201%2C%20Dubai', null, '/images/interior-joker-mural.webp', true, false, 'Address and phone from madnessmadeindubai.shop (not confirmed as official). Instagram lists a Jumeirah highlight. Hours unknown.', 2)
