insert into public.menu_items (id, category_id, name, slug, short_description, description, price, image_url, image_alt, ingredients, allergens, allergens_verified, dietary_labels, is_available, is_featured, is_sample, display_order) values
  ('d0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'Smoking Popcorn Chicken & Fries', 'smoking-popcorn-chicken-fries', 'Sticky glazed chicken over fries, served in a cloud of smoke.', 'Crispy popcorn chicken tossed in a sticky glaze, stacked over golden fries and brought to the table on a bed of dry-ice fog.', 52, '/images/smoking-chicken-fries.webp', 'Glazed popcorn chicken piled on fries in a tall glass, set over a bowl of rolling dry-ice fog', array['Chicken', 'Fries', 'Sticky glaze', 'Spring onion', 'Sesame seeds']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 1),
  ('d0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000001', 'Glazed Chicken Skewers', 'glazed-chicken-skewers', 'Lacquered skewers with a bright, creamy dip.', 'Chargrilled skewers brushed with a sweet and savoury glaze, finished with herbs and served with a creamy dipping sauce.', 48, '/images/skewers-glazed.webp', 'Lacquered chicken skewers on a banana leaf with a pot of yellow dipping sauce', array['Chicken', 'Glaze', 'Herbs', 'Dipping sauce']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 2),
  ('d0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000001', 'Parmesan Mozzarella Sticks', 'parmesan-mozzarella-sticks', 'Crisp outside, molten inside, buried in parmesan.', 'Breaded mozzarella fried until golden, showered with parmesan, chives and chilli, with a creamy dip.', 39, '/images/mozzarella-sticks.webp', 'Golden mozzarella sticks dusted with grated cheese and chilli, with a dip on the side', array['Mozzarella', 'Breadcrumbs', 'Parmesan', 'Chives', 'Chilli', 'Dip']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 3),
  ('d0000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000001', 'Loaded Fries Skillet', 'loaded-fries-skillet', 'Fries, molten cheese and seasoned beef in cast iron.', 'A cast-iron skillet of fries smothered in melted cheese, seasoned minced beef, tomato and herbs.', 42, '/images/loaded-fries-skillet.webp', 'Cast-iron skillet of fries covered in melted cheese, minced beef and diced tomato', array['Fries', 'Cheese sauce', 'Minced beef', 'Tomato', 'Herbs']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 4),
  ('d0000000-0000-4000-8000-000000000005', 'c0000000-0000-4000-8000-000000000001', 'Street Corn Skewers', 'street-corn-skewers', 'Charred corn on sticks, dressed to impress.', 'Grilled corn cut into rounds, skewered and finished with seasoning and sauce.', 32, '/images/chef-corn-skewers.webp', 'A masked MADNESS chef holding a plate of charred corn skewers', array['Corn', 'Seasoning', 'Sauce']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 5),
  ('d0000000-0000-4000-8000-000000000006', 'c0000000-0000-4000-8000-000000000002', 'Burrata & Berries', 'burrata-berries', 'Creamy burrata, fresh berries, basil and balsamic.', 'Soft burrata with raspberries, pomegranate, grapes and basil, finished with a balsamic glaze.', 58, '/images/burrata-berries.webp', 'Burrata surrounded by raspberries, grapes and basil with a balsamic drizzle', array['Burrata', 'Raspberries', 'Pomegranate', 'Grapes', 'Basil', 'Balsamic glaze']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 6),
  ('d0000000-0000-4000-8000-000000000007', 'c0000000-0000-4000-8000-000000000003', 'Hot Stone Wagyu', 'hot-stone-wagyu', 'Marbled beef you sear yourself on a smoking stone.', 'Thinly sliced marbled beef served raw with a volcanic hot stone, so you can sear each slice at the table. Comes with a dipping sauce.', 145, '/images/hot-stone-wagyu.webp', 'Thin slices of marbled beef being seared on a smoking hot stone at the table', array['Wagyu beef', 'Dipping sauce']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 7),
  ('d0000000-0000-4000-8000-000000000008', 'c0000000-0000-4000-8000-000000000004', 'Double Trouble Burger', 'double-trouble-burger', 'Two patties, double cheese, house sauce.', 'Two beef patties with melted cheese, smashed avocado, frisée and a rich house sauce in a toasted sesame brioche bun.', 68, '/images/burger-double-dark.webp', 'Double beef burger with melted cheese, house sauce and frisée lettuce on a brioche bun', array['Beef patties', 'Cheese', 'Avocado', 'Frisée', 'House sauce', 'Sesame brioche bun']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 8),
  ('d0000000-0000-4000-8000-000000000009', 'c0000000-0000-4000-8000-000000000004', 'Woodboard Cheeseburger', 'woodboard-cheeseburger', 'Melted cheese, crispy onions and a jalapeño kick.', 'A juicy beef patty with melted cheese, crispy fried onions, jalapeños and lettuce in a glossy brioche bun.', 59, '/images/burger-woodboard.webp', 'Cheeseburger with crispy onions and jalapeños served on stacked wooden rounds', array['Beef patty', 'Cheese', 'Crispy onions', 'Jalapeños', 'Lettuce', 'Brioche bun']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 9),
  ('d0000000-0000-4000-8000-000000000010', 'c0000000-0000-4000-8000-000000000004', 'Slider Duo', 'slider-duo', 'Two mini burgers, one big attitude.', 'A pair of mini beef sliders with cheese and sauce on soft buns.', 49, '/images/chef-sliders.webp', 'A masked chef in a leather booth presenting two mini burgers', array['Beef', 'Cheese', 'Sauce', 'Mini buns']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 10),
  ('d0000000-0000-4000-8000-000000000011', 'c0000000-0000-4000-8000-000000000005', 'Pink Sauce Fusilli', 'pink-sauce-fusilli', 'Creamy tomato fusilli served straight from the foil.', 'Long fusilli in a silky tomato and cream sauce, baked and served in its foil parcel.', 62, '/images/pasta-fusilli-mask.webp', 'Long fusilli in a creamy pink sauce lifted from a foil parcel, a clown mask in the background', array['Fusilli', 'Tomato', 'Cream', 'Parmesan']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 11),
  ('d0000000-0000-4000-8000-000000000012', 'c0000000-0000-4000-8000-000000000005', 'Tagliatelle Ragù', 'tagliatelle-ragu', 'Slow-cooked ragù, ribbons of pasta, plenty of cheese.', 'Fresh tagliatelle with a slow-cooked meat ragù, finished with grated cheese and thyme.', 72, '/images/pasta-ragu.webp', 'Tagliatelle twirled with slow-cooked meat ragù, grated cheese and thyme', array['Tagliatelle', 'Meat ragù', 'Grated cheese', 'Thyme']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 12),
  ('d0000000-0000-4000-8000-000000000013', 'c0000000-0000-4000-8000-000000000005', 'Tagliatelle Pomodoro', 'tagliatelle-pomodoro', 'Bright tomato sauce, fresh basil, parmesan.', 'Tagliatelle tossed in a simple tomato sauce with fresh basil and shaved parmesan.', 55, '/images/pasta-pomodoro.webp', 'Tagliatelle in a bright tomato sauce topped with fresh basil and parmesan shavings', array['Tagliatelle', 'Tomato sauce', 'Basil', 'Parmesan']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 13),
  ('d0000000-0000-4000-8000-000000000014', 'c0000000-0000-4000-8000-000000000005', 'Skillet Pasta', 'skillet-pasta', 'Creamy pasta, served sizzling in the pan.', 'Creamy pasta finished with cheese and herbs, served in a hot skillet.', 66, '/images/chef-pasta-skillet.webp', 'A masked chef in black gloves holding a skillet of creamy pasta', array['Pasta', 'Cream sauce', 'Cheese', 'Herbs']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 14),
  ('d0000000-0000-4000-8000-000000000015', 'c0000000-0000-4000-8000-000000000006', 'Chocolate Lava Cake', 'chocolate-lava-cake', 'Molten chocolate, vanilla ice cream, cherries.', 'A warm chocolate fondant with a molten centre, vanilla ice cream, cherry compote and spun sugar.', 42, '/images/dessert-lava-cake.webp', 'Chocolate fondant with vanilla ice cream, cherry compote and a spun-sugar garnish', array['Dark chocolate', 'Vanilla ice cream', 'Cherry compote', 'Spun sugar']::text[], '{}'::text[], false, '{}'::text[], true, true, true, 15),
  ('d0000000-0000-4000-8000-000000000016', 'c0000000-0000-4000-8000-000000000006', 'Berry Sphere', 'berry-sphere', 'Glossy berry mousse dome with crumble and sugar lace.', 'A berry-glazed mousse dome with fresh berries, crumble and a caramel lattice.', 48, '/images/dessert-sphere.webp', 'Glazed red dessert sphere with fresh berries, crumble and an amber sugar lattice', array['Berry mousse', 'Fresh berries', 'Crumble', 'Caramel']::text[], '{}'::text[], false, '{}'::text[], true, false, true, 16)
