  ('e0000000-0000-4000-8000-000000000002', '/images/smoking-chicken-fries.webp', 'Glazed chicken over fries served on rolling dry-ice fog', 'Served with a little smoke.', 'Unleash your appetite. Discover a different kind of dining experience.', 'Explore the menu', '/menu', 'Order now', '/#order', 2, true),
