  ('e0000000-0000-4000-8000-000000000004', '/images/interior-neon-booths.webp', 'Leather booths under pink neon signs inside MADNESS', 'Step inside the madness.', 'Unleash your appetite. Discover a different kind of dining experience.', 'Explore the menu', '/menu', 'Order now', '/#order', 4, true)
