insert into public.site_settings (key, value) values
  ('site_name', '"MADNESS"'::jsonb),
  ('tagline', '"Unleash your appetite."'::jsonb),
  ('footer_blurb', '"A themed restaurant in the UAE where bold food meets comic-book chaos."'::jsonb),
  ('instagram_url', '"https://www.instagram.com/madness.uae/"'::jsonb),
  ('tiktok_url', 'null'::jsonb),
  ('facebook_url', 'null'::jsonb),
  ('contact_email', 'null'::jsonb),
  ('contact_phone', 'null'::jsonb),
  ('google_reviews_url', 'null'::jsonb),
  ('home_about_heading', '"Not just a meal. An experience."'::jsonb),
  ('home_about_body', '"At MADNESS, dinner comes with a show. Masked chefs, neon on every wall and plates that arrive smoking, sizzling or stacked sky high. Come hungry and leave with a story."'::jsonb),
  ('home_about_image', '"/images/chef-smoking-dish.webp"'::jsonb),
  ('about_intro', '"MADNESS is a villain-themed restaurant where every plate is a little bit of theatre."'::jsonb),
  ('about_story', '"This is where the MADNESS story goes: how it started, who is behind it and what drives the team. Replace this paragraph in Admin, Content, with details supplied by the restaurant."'::jsonb),
  ('about_philosophy', '"Bold flavours, generous portions and presentation that makes the whole table reach for their phones. Replace with the kitchen''s own words."'::jsonb),
  ('about_atmosphere', '"Tufted leather booths, neon slogans, graffiti murals and a team in masks who stay in character. It is loud, playful and a little bit unhinged, in the best way."'::jsonb),
  ('show_sample_notice', 'true'::jsonb)
